from typing import List, Dict, Any, Optional
from datetime import datetime

class MetricPoint:
    def __init__(self, timestamp: float, value: float):
        self.timestamp = timestamp
        self.value = value

class MetricSeries:
    def __init__(self, metadata: Dict[str, str], data: List[MetricPoint]):
        self.metadata = metadata
        self.data = data

class MetricQueryResult:
    def __init__(self, name: str, unit: str, timeseries: List[MetricSeries]):
        self.name = name
        self.unit = unit
        self.timeseries = timeseries

class AggregatedMetricValue:
    def __init__(self, timestamp: float, average: Optional[float] = None,
                 minimum: Optional[float] = None, maximum: Optional[float] = None,
                 total: Optional[float] = None, count: Optional[float] = None):
        self.timestamp = timestamp
        self.average = average
        self.minimum = minimum
        self.maximum = maximum
        self.total = total
        self.count = count

class MetricAggregationResult:
    def __init__(self, name: str, unit: str, values: List[AggregatedMetricValue]):
        self.name = name
        self.unit = unit
        self.values = values

import os
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient
from azure.ai.textanalytics import TextAnalyticsClient
from azure.ai.translation.text import TextTranslationClient, TranslatorCredential
from azure.storage.blob import BlobServiceClient

def get_metrics_query_client():
    credential = DefaultAzureCredential()
    return MetricsQueryClient(credential=credential)

def get_text_analytics_client(endpoint: str, key: str):
    credential = DefaultAzureCredential()
    return TextAnalyticsClient(endpoint=endpoint, credential=credential)

def get_translator_client(endpoint: str, key: str, region: str):
